/usr/bin/zsh -lc "python3 -B - <<'PY'
import subprocess
from service import save as staged_save
from store import ReceiptUnavailable, Store

baseline = {}
exec(compile(subprocess.check_output(['git', 'show', 'HEAD:service.py'], text=True), 'HEAD:service.py', 'exec'), baseline)

def fresh_operation(save):
    store = Store()
    save(store, 'w', 'op-1', {'color': 'blue'})
    result = save(store, 'w', 'op-2', {'color': 'red'})
    return {'result': result, 'preferences': store.preferences['w'], 'recovery_ids': list(store.recovery)}

def edited_retry(save):
    store = Store()
    store.fail_receipt_once = True
    try:
        save(store, 'w', 'op-1', {'color': 'blue'})
    except ReceiptUnavailable:
        pass
    result = save(store, 'w', 'op-1', {'color': 'red'})
    return {'result': result, 'preferences': store.preferences['w'], 'recovery_values': store.recovery['op-1']['values']}

def completed_retry(save):
    store = Store()
    save(store, 'w', 'op-1', {'color': 'blue'})
    store.fail_receipt_once = True
    try:
        result = save(store, 'w', 'op-1', {'color': 'blue'})
        return {'result': result}
    except ReceiptUnavailable as error:
        return {'error': type(error).__name__}

for case in (fresh_operation, edited_retry, completed_retry):
    print(case.__name__)
    print('  HEAD:', case(baseline['save']))
    print('  staged:', case(staged_save))
PY"

